import {runProject} from './engine.js?v=1.9.0';
// Uses the exact engine queries, including temperature iterations. Screening totals are never presented as analysis results.
export function screenProject(project,progress=()=>{}){const result=runProject({...project,operating:{...project.operating,projectionScreen:true}},progress),groups=new Map();for(const row of result.rows)for(const device of row.devices)for(const issue of device.projectionProblems||[]){if(issue.accepted)continue;const key=device.instanceId+':'+device.candidateId+':'+issue.curveId;let group=groups.get(key);if(!group){group={...issue,instanceId:device.instanceId,candidateId:device.candidateId,device:device.instanceName,part:device.part,points:[],deviceResult:device};groups.set(key,group);}if(!group.points.includes(row.waveformId))group.points.push(row.waveformId);if(issue.minRaw<group.minRaw){group.minRaw=issue.minRaw;group.query=issue.query;}}return {issues:[...groups.values()],failures:result.errors,result};}
